# normalize shape and generate dihedral orientations

def norm(shape):
    mr=min(r for r,c in shape); mc=min(c for r,c in shape)
    return tuple(sorted((r-mr,c-mc) for r,c in shape))
def transforms(shape):
    ts=set()
    for flip in [1,-1]:
      for rot in range(4):
       coords=[]
       for r,c in shape:
        x,y=r,flip*c
        for _ in range(rot): x,y=y,-x
        coords.append((x,y))
       ts.add(norm(coords))
    return ts
